SELECT 'CURRENCY' key, 'ENTERPRISE_ID~CURRENCY_CODE~ENABLED_FLAG~CURRENCY_FLAG~ISSUING_TERRITORY_CODE~PRECISION~EXTENDED_PRECISION~START_DATE_ACTIVE~END_DATE_ACTIVE~ISO_FLAG~ATTRIBUTE_DATE1~ATTRIBUTE_DATE2~ATTRIBUTE_DATE3~ATTRIBUTE_DATE4~ATTRIBUTE_DATE5~ATTRIBUTE_DATE6~ATTRIBUTE_DATE7~ATTRIBUTE_DATE8~ATTRIBUTE_DATE9~ATTRIBUTE_DATE10~ATTRIBUTE_TIMESTAMP1~ATTRIBUTE_TIMESTAMP2~ATTRIBUTE_TIMESTAMP3~ATTRIBUTE_TIMESTAMP4~ATTRIBUTE_TIMESTAMP5~ATTRIBUTE_TIMESTAMP6~ATTRIBUTE_TIMESTAMP7~ATTRIBUTE_TIMESTAMP8~ATTRIBUTE_TIMESTAMP9~ATTRIBUTE_TIMESTAMP10~DERIVE_EFFECTIVE~CREATION_DATE~CREATED_BY~LAST_UPDATE_DATE~LAST_UPDATED_BY~LAST_UPDATE_LOGIN~GLOBAL_ATTRIBUTE_DATE1~GLOBAL_ATTRIBUTE_DATE2~GLOBAL_ATTRIBUTE_DATE3~GLOBAL_ATTRIBUTE_DATE4~GLOBAL_ATTRIBUTE_DATE5~GLOBAL_ATTRIBUTE_TIMESTAMP1~GLOBAL_ATTRIBUTE_TIMESTAMP2~GLOBAL_ATTRIBUTE_TIMESTAMP3~GLOBAL_ATTRIBUTE_TIMESTAMP4~GLOBAL_ATTRIBUTE_TIMESTAMP5~SYMBOL~DERIVE_TYPE~DERIVE_FACTOR~MINIMUM_ACCOUNTABLE_UNIT' CURRENCY 
FROM DUAL
UNION ALL
SELECT  'CURRENCY' key, ENTERPRISE_ID||'|'||CURRENCY_CODE||'|'||ENABLED_FLAG||'|'||CURRENCY_FLAG||'|'||ISSUING_TERRITORY_CODE||'|'||PRECISION||'|'||EXTENDED_PRECISION||'|'||START_DATE_ACTIVE||'|'||END_DATE_ACTIVE||'|'||ISO_FLAG||'|'||ATTRIBUTE_DATE1||'|'||ATTRIBUTE_DATE2||'|'||ATTRIBUTE_DATE3||'|'||ATTRIBUTE_DATE4||'|'||ATTRIBUTE_DATE5||'|'||ATTRIBUTE_DATE6||'|'||ATTRIBUTE_DATE7||'|'||ATTRIBUTE_DATE8||'|'||ATTRIBUTE_DATE9||'|'||ATTRIBUTE_DATE10||'|'||ATTRIBUTE_TIMESTAMP1||'|'||ATTRIBUTE_TIMESTAMP2||'|'||ATTRIBUTE_TIMESTAMP3||'|'||ATTRIBUTE_TIMESTAMP4||'|'||ATTRIBUTE_TIMESTAMP5||'|'||ATTRIBUTE_TIMESTAMP6||'|'||ATTRIBUTE_TIMESTAMP7||'|'||ATTRIBUTE_TIMESTAMP8||'|'||ATTRIBUTE_TIMESTAMP9||'|'||ATTRIBUTE_TIMESTAMP10||'|'||DERIVE_EFFECTIVE||'|'||CREATION_DATE||'|'||CREATED_BY||'|'||LAST_UPDATE_DATE||'|'||LAST_UPDATED_BY||'|'||LAST_UPDATE_LOGIN||'|'||GLOBAL_ATTRIBUTE_DATE1||'|'||GLOBAL_ATTRIBUTE_DATE2||'|'||GLOBAL_ATTRIBUTE_DATE3||'|'||GLOBAL_ATTRIBUTE_DATE4||'|'||GLOBAL_ATTRIBUTE_DATE5||'|'||GLOBAL_ATTRIBUTE_TIMESTAMP1||'|'||
GLOBAL_ATTRIBUTE_TIMESTAMP2||'|'||GLOBAL_ATTRIBUTE_TIMESTAMP3||'|'||GLOBAL_ATTRIBUTE_TIMESTAMP4||'|'||GLOBAL_ATTRIBUTE_TIMESTAMP5||'|'||SYMBOL||'|'||DERIVE_TYPE||'|'||DERIVE_FACTOR||'|'||MINIMUM_ACCOUNTABLE_UNIT  
FROM  FND_CURRENCIES a
WHERE ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND a.last_update_date > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_CURRENCY'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument3'
                             	          AND ERP.value IS NOT NULL)))
ORDER BY 1 DESC